int parse_ethernet(const uint8_t *p, size_t n, Ethernet *out) {
    if (!p || !out || n < 14) return -1;
    Ethernet e = {0};
    e.type = (uint16_t)(p[12] << 8 | p[13]);
    e.payload = 14;
    if (e.type == 0x8100) {
        e.type = (uint16_t)(p[16] << 8 | p[17]);
        e.payload = 18;
    }
    *out = e;
    return 0;
}
